59|/*
60| * Malloc failure injection.
61| *
62| * To debug issues involving malloc failures, it's often helpful to set
63| * MALLOC_ABORT to 1. This should provide a backtrace of the failed
64| * allocation.
65| */
66|
67|#define XML_FUZZ_MALLOC_ABORT   0
68|
69|static void *
70|xmlFuzzMalloc(size_t size) {
71|    if (fuzzMaxAllocs > 0) {
72|        fuzzNumAllocs += 1;
73|        if (fuzzNumAllocs == fuzzMaxAllocs) {
74|#if XML_FUZZ_MALLOC_ABORT
75|            abort();
76|#endif
77|            fuzzAllocFailed = 1;
78|            return(NULL);
79|        }
80|    }
81|    return malloc(size);
82|}
83|
84|static void *
85|xmlFuzzRealloc(void *ptr, size_t size) {
86|    if (fuzzMaxAllocs > 0) {
87|        fuzzNumAllocs += 1;
88|        if (fuzzNumAllocs == fuzzMaxAllocs) {
89|#if XML_FUZZ_MALLOC_ABORT
90|            abort();
91|#endif
92|            fuzzAllocFailed = 1;
93|            return(NULL);
94|        }
95|    }
96|    return realloc(ptr, size);
97|}
