161|/**
162| * xmlFuzzWriteInt:
163| * @out:  output file
164| * @v:  integer to write
165| * @size:  size of integer in bytes
166| *
167| * Write an integer to the fuzz data.
168| */
169|void
170|xmlFuzzWriteInt(FILE *out, size_t v, int size) {
171|    int shift;
172|
173|    while (size > (int) sizeof(size_t)) {
174|        putc(0, out);
175|        size--;
176|    }
177|
178|    shift = size * 8;
179|    while (shift > 0) {
180|        shift -= 8;
181|        putc((v >> shift) & 255, out);
182|    }
183|}
184|
185|/**
186| * xmlFuzzReadInt:
187| * @size:  size of integer in bytes
188| *
189| * Read an integer from the fuzz data.
190| */
191|size_t
192|xmlFuzzReadInt(int size) {
193|    size_t ret = 0;
194|
195|    while ((size > 0) && (fuzzData.remaining > 0)) {
196|        unsigned char c = (unsigned char) *fuzzData.ptr++;
197|        fuzzData.remaining--;
198|        ret = (ret << 8) | c;
199|        size--;
200|    }
201|
202|    return ret;
203|}
