295|/**
296| * xmlFuzzReadEntities:
297| *
298| * Read entities like the main XML file, external DTDs, external parsed
299| * entities from fuzz data.
300| */
301|void
302|xmlFuzzReadEntities(void) {
303|    size_t num = 0;
304|
305|    while (1) {
306|        const char *url, *entity;
307|        size_t entitySize;
308|        xmlFuzzEntityInfo *entityInfo;
309|
310|        url = xmlFuzzReadString(NULL);
311|        if (url == NULL) break;
312|
313|        entity = xmlFuzzReadString(&entitySize);
314|        if (entity == NULL) break;
315|
316|        if (xmlHashLookup(fuzzData.entities, (xmlChar *)url) == NULL) {
317|            entityInfo = xmlMalloc(sizeof(xmlFuzzEntityInfo));
318|            if (entityInfo == NULL)
319|                break;
320|            entityInfo->data = entity;
321|            entityInfo->size = entitySize;
322|
323|            xmlHashAddEntry(fuzzData.entities, (xmlChar *)url, entityInfo);
324|
325|            if (num == 0) {
326|                fuzzData.mainUrl = url;
327|                fuzzData.mainEntity = entityInfo;
328|            }
329|
330|            num++;
331|        }
332|    }
333|}
