359|/**
360| * xmlFuzzEntityLoader:
361| *
362| * The entity loader for fuzz data.
363| */
364|xmlParserInputPtr
365|xmlFuzzEntityLoader(const char *URL, const char *ID ATTRIBUTE_UNUSED,
366|                    xmlParserCtxtPtr ctxt) {
367|    xmlParserInputPtr input;
368|    xmlFuzzEntityInfo *entity;
369|
370|    if (URL == NULL)
371|        return(NULL);
372|    entity = xmlHashLookup(fuzzData.entities, (xmlChar *) URL);
373|    if (entity == NULL)
374|        return(NULL);
375|
376|    input = xmlNewInputStream(ctxt);
377|    if (input == NULL)
378|        return(NULL);
379|    input->filename = (char *) xmlCharStrdup(URL);
380|    if (input->filename == NULL) {
381|        xmlCtxtErrMemory(ctxt);
382|        xmlFreeInputStream(input);
383|        return(NULL);
384|    }
385|    input->buf = xmlParserInputBufferCreateMem(entity->data, entity->size,
386|                                               XML_CHAR_ENCODING_NONE);
387|    if (input->buf == NULL) {
388|        xmlCtxtErrMemory(ctxt);
389|        xmlFreeInputStream(input);
390|        return(NULL);
391|    }
392|    input->base = input->cur = xmlBufContent(input->buf->buffer);
393|    input->end = input->base + xmlBufUse(input->buf->buffer);
394|
395|    return input;
396|}
