332|xmlXIncludeFreeContext(xmlXIncludeCtxtPtr ctxt) {
333|    int i;
334|
335|    if (ctxt == NULL)
336|	return;
337|    if (ctxt->urlTab != NULL) {
338|	for (i = 0; i < ctxt->urlNr; i++) {
339|	    xmlFreeDoc(ctxt->urlTab[i].doc);
340|	    xmlFree(ctxt->urlTab[i].url);
341|	}
342|	xmlFree(ctxt->urlTab);
343|    }
344|    for (i = 0;i < ctxt->incNr;i++) {
345|	if (ctxt->incTab[i] != NULL)
346|	    xmlXIncludeFreeRef(ctxt->incTab[i]);
347|    }
348|    if (ctxt->incTab != NULL)
