433|    if ((URL != NULL) && (strcmp(URL, "-") == 0))
434|        URL = "./-";
435|
436|    inputStream = xmlLoadExternalEntity(URL, NULL, pctxt);
437|    if (inputStream == NULL)
438|        goto error;
439|
440|    inputPush(pctxt, inputStream);
441|
442|    if (pctxt->directory == NULL) {
443|        pctxt->directory = xmlParserGetDirectory(URL);
444|        if (pctxt->directory == NULL) {
