2031|	    if ((children->type == XML_ELEMENT_NODE) &&
2032|		(children->ns != NULL) &&
2033|		(xmlStrEqual(children->name, XINCLUDE_FALLBACK)) &&
2034|		((xmlStrEqual(children->ns->href, XINCLUDE_NS)) ||
2035|		 (xmlStrEqual(children->ns->href, XINCLUDE_OLD_NS)))) {
2036|		ret = xmlXIncludeLoadFallback(ctxt, children, ref);
