2077|    list = ref->inc;
2078|    ref->inc = NULL;
2079|    ref->emptyFb = 0;
2080|
2081|    /*
2082|     * Check against the risk of generating a multi-rooted document
2083|     */
2084|    if ((cur->parent != NULL) &&
2085|	(cur->parent->type != XML_ELEMENT_NODE)) {
2086|	int nb_elem = 0;
2087|
2088|	tmp = list;
2089|	while (tmp != NULL) {
2090|	    if (tmp->type == XML_ELEMENT_NODE)
2091|		nb_elem++;
2092|	    tmp = tmp->next;
2093|	}
2094|	if (nb_elem > 1) {
2095|	    xmlXIncludeErr(ctxt, ref->elem, XML_XINCLUDE_MULTIPLE_ROOT,
2096|		       "XInclude error: would result in multiple root nodes\n",
2097|			   NULL);
