2103|    if (ctxt->parseFlags & XML_PARSE_NOXINCNODE) {
2104|	/*
2105|	 * Add the list of nodes
2106|	 */
2107|	while (list != NULL) {
2108|	    end = list;
2109|	    list = list->next;
2110|
2111|	    xmlAddPrevSibling(cur, end);
2112|	}
2113|        /*
2114|         * FIXME: xmlUnlinkNode doesn't coalesce text nodes.
2115|         */
2116|	xmlUnlinkNode(cur);
2117|	xmlFreeNode(cur);
2118|    } else {
2119|        xmlNodePtr child, next;
2120|
2121|	/*
2122|	 * Change the current node as an XInclude start one, and add an
2123|	 * XInclude end one
