2125|        if (ref->fallback)
2126|            xmlUnsetProp(cur, BAD_CAST "href");
2127|	cur->type = XML_XINCLUDE_START;
2128|        /* Remove fallback children */
2129|        for (child = cur->children; child != NULL; child = next) {
2130|            next = child->next;
2131|            xmlUnlinkNode(child);
2132|            xmlFreeNode(child);
2133|        }
