2181|	               "Deprecated XInclude namespace found, use %s",
2182|		                XINCLUDE_NS);
2183|#endif
2184|	        ctxt->legacy = 1;
2185|	    }
2186|	}
2187|	if (xmlStrEqual(node->name, XINCLUDE_NODE)) {
2188|	    xmlNodePtr child = node->children;
