2211|			       "%s has multiple fallback children\n",
2212|		               XINCLUDE_NODE);
2213|		return(0);
2214|	    }
2215|	    return(1);
2216|	}
2217|	if (xmlStrEqual(node->name, XINCLUDE_FALLBACK)) {
2218|	    if ((node->parent == NULL) ||
2219|		(node->parent->type != XML_ELEMENT_NODE) ||
