242|/**
243| * xmlXIncludeNewRef:
244| * @ctxt: the XInclude context
245| * @URI:  the resource URI
246| * @elem:  the xi:include element
247| *
248| * Creates a new reference within an XInclude context
249| *
250| * Returns the new set
251| */
252|static xmlXIncludeRefPtr
253|xmlXIncludeNewRef(xmlXIncludeCtxtPtr ctxt, const xmlChar *URI,
254|	          xmlNodePtr elem) {
255|    xmlXIncludeRefPtr ret;
256|
257|    ret = (xmlXIncludeRefPtr) xmlMalloc(sizeof(xmlXIncludeRef));
258|    if (ret == NULL) {
259|        xmlXIncludeErrMemory(ctxt, elem, "growing XInclude context");
260|	return(NULL);
261|    }
262|    memset(ret, 0, sizeof(xmlXIncludeRef));
263|    if (URI == NULL) {
264|	ret->URI = NULL;
265|    } else {
266|	ret->URI = xmlStrdup(URI);
267|        if (ret->URI == NULL) {
268|            xmlXIncludeErrMemory(ctxt, elem, NULL);
269|            xmlXIncludeFreeRef(ret);
270|            return(NULL);
271|        }
272|    }
273|    ret->fragment = NULL;
274|    ret->elem = elem;
275|    ret->xml = 0;
276|    ret->inc = NULL;
277|    if (ctxt->incNr >= ctxt->incMax) {
278|        xmlXIncludeRefPtr *tmp;
279|#ifdef FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
280|        size_t newSize = ctxt->incMax ? ctxt->incMax * 2 : 1;
281|#else
282|        size_t newSize = ctxt->incMax ? ctxt->incMax * 2 : 4;
283|#endif
284|
285|        tmp = (xmlXIncludeRefPtr *) xmlRealloc(ctxt->incTab,
286|	             newSize * sizeof(ctxt->incTab[0]));
287|        if (tmp == NULL) {
288|	    xmlXIncludeErrMemory(ctxt, elem, "growing XInclude context");
289|	    xmlXIncludeFreeRef(ret);
290|	    return(NULL);
291|	}
292|        ctxt->incTab = tmp;
293|        ctxt->incMax = newSize;
294|    }
295|    ctxt->incTab[ctxt->incNr++] = ret;
296|    return(ret);
297|}
