365|static xmlChar *
366|xmlXIncludeBuildURI(xmlXIncludeCtxtPtr ctxt, xmlNodePtr cur,
367|                    const xmlChar *base, int *xmlOut) {
368|    xmlChar *href = NULL;
369|    xmlChar *parse = NULL;
370|    xmlChar *URI = NULL;
371|    int xml = 1;
372|
373|    /*
374|     * read the attributes
375|     */
376|    href = xmlXIncludeGetProp(ctxt, cur, XINCLUDE_HREF);
377|    if (href == NULL) {
378|	href = xmlStrdup(BAD_CAST ""); /* @@@@ href is now optional */
379|	if (href == NULL) {
380|            xmlXIncludeErrMemory(ctxt, cur, NULL);
381|	    goto error;
382|        }
383|    }
384|    parse = xmlXIncludeGetProp(ctxt, cur, XINCLUDE_PARSE);
385|    if (parse != NULL) {
386|	if (xmlStrEqual(parse, XINCLUDE_PARSE_XML))
387|	    xml = 1;
388|	else if (xmlStrEqual(parse, XINCLUDE_PARSE_TEXT))
389|	    xml = 0;
390|	else {
391|	    xmlXIncludeErr(ctxt, cur, XML_XINCLUDE_PARSE_VALUE,
392|	                   "invalid value %s for 'parse'\n", parse);
393|	    goto error;
394|	}
395|    }
396|
397|    /*
398|     * compute the URI
399|     */
400|    if (xmlBuildURISafe(href, base, &URI) < 0) {
401|        xmlXIncludeErrMemory(ctxt, NULL, NULL);
402|        goto error;
403|    }
404|    if (URI == NULL)
405|	xmlXIncludeErr(ctxt, cur, XML_XINCLUDE_HREF_URI,
406|                       "failed build URL\n", NULL);
407|
408|error:
409|    xmlFree(href);
410|    xmlFree(parse);
411|    *xmlOut = xml;
412|    return(URI);
413|}
