415|/**
416| * xmlXIncludeParseFile:
417| * @ctxt:  the XInclude context
418| * @URL:  the URL or file path
419| *
420| * parse a document for XInclude
421| */
422|static xmlDocPtr
423|xmlXIncludeParseFile(xmlXIncludeCtxtPtr ctxt, const char *URL) {
424|    xmlDocPtr ret = NULL;
425|    xmlParserCtxtPtr pctxt;
426|    xmlParserInputPtr inputStream;
427|
428|    xmlInitParser();
429|
430|    pctxt = xmlNewParserCtxt();
431|    if (pctxt == NULL) {
432|	xmlXIncludeErrMemory(ctxt, NULL, "cannot allocate parser context");
433|	return(NULL);
434|    }
435|
436|    /*
437|     * pass in the application data to the parser context.
438|     */
439|    pctxt->_private = ctxt->_private;
440|
441|    /*
442|     * try to ensure that new documents included are actually
443|     * built with the same dictionary as the including document.
444|     */
445|    if ((ctxt->doc != NULL) && (ctxt->doc->dict != NULL)) {
446|       if (pctxt->dict != NULL)
447|            xmlDictFree(pctxt->dict);
448|	pctxt->dict = ctxt->doc->dict;
449|	xmlDictReference(pctxt->dict);
450|    }
451|
452|    xmlCtxtUseOptions(pctxt, ctxt->parseFlags | XML_PARSE_DTDLOAD);
453|
454|    /* Don't read from stdin. */
455|    if ((URL != NULL) && (strcmp(URL, "-") == 0))
456|        URL = "./-";
457|
458|    inputStream = xmlLoadExternalEntity(URL, NULL, pctxt);
459|    if (inputStream == NULL)
460|        goto error;
461|
462|    inputPush(pctxt, inputStream);
463|
464|    if (pctxt->directory == NULL) {
465|        pctxt->directory = xmlParserGetDirectory(URL);
466|        if (pctxt->directory == NULL) {
467|            xmlXIncludeErrMemory(ctxt, NULL, NULL);
468|            goto error;
469|        }
470|    }
471|
472|    pctxt->loadsubset |= XML_DETECT_IDS;
473|
474|    xmlParseDocument(pctxt);
475|
476|    if (pctxt->wellFormed) {
477|        ret = pctxt->myDoc;
478|    }
479|    else {
480|        ret = NULL;
481|	if (pctxt->myDoc != NULL)
482|	    xmlFreeDoc(pctxt->myDoc);
483|        pctxt->myDoc = NULL;
484|    }
485|
486|error:
487|    if (pctxt->errNo == XML_ERR_NO_MEMORY)
488|        xmlXIncludeErrMemory(ctxt, NULL, NULL);
489|    xmlFreeParserCtxt(pctxt);
490|
491|    return(ret);
492|}
