494|/**
495| * xmlXIncludeAddNode:
496| * @ctxt:  the XInclude context
497| * @cur:  the new node
498| *
499| * Add a new node to process to an XInclude context
500| */
501|static xmlXIncludeRefPtr
502|xmlXIncludeAddNode(xmlXIncludeCtxtPtr ctxt, xmlNodePtr cur) {
503|    xmlXIncludeRefPtr ref;
504|    xmlURIPtr uri;
505|    xmlChar *URL;
506|    xmlChar *fragment = NULL;
507|    xmlChar *base;
508|    xmlChar *URI;
509|    int xml;
510|    int local = 0;
511|    int res;
512|
513|    if (ctxt == NULL)
514|	return(NULL);
515|    if (cur == NULL)
516|	return(NULL);
517|
518|    if (xmlNodeGetBaseSafe(ctxt->doc, cur, &base) < 0) {
519|        xmlXIncludeErrMemory(ctxt, NULL, NULL);
520|        return(NULL);
521|    }
522|    URI = xmlXIncludeBuildURI(ctxt, cur, base, &xml);
523|    xmlFree(base);
524|    if (URI == NULL)
525|	return(NULL);
526|    fragment = xmlXIncludeGetProp(ctxt, cur, XINCLUDE_PARSE_XPOINTER);
527|
528|    /*
529|     * Check the URL and remove any fragment identifier
530|     */
531|    res = xmlParseURISafe((const char *)URI, &uri);
532|    if (uri == NULL) {
533|        if (res < 0)
534|            xmlXIncludeErrMemory(ctxt, NULL, NULL);
535|        else
536|            xmlXIncludeErr(ctxt, cur, XML_XINCLUDE_HREF_URI,
537|                           "invalid value URI %s\n", URI);
538|	if (fragment != NULL)
539|	    xmlFree(fragment);
540|	xmlFree(URI);
541|	return(NULL);
542|    }
543|
544|    if (uri->fragment != NULL) {
545|        if (ctxt->legacy != 0) {
546|	    if (fragment == NULL) {
547|		fragment = (xmlChar *) uri->fragment;
548|	    } else {
549|		xmlFree(uri->fragment);
550|	    }
551|	} else {
552|	    xmlXIncludeErr(ctxt, cur, XML_XINCLUDE_FRAGMENT_ID,
553|       "Invalid fragment identifier in URI %s use the xpointer attribute\n",
554|                           URI);
555|	    if (fragment != NULL)
556|	        xmlFree(fragment);
557|	    xmlFreeURI(uri);
558|	    xmlFree(URI);
559|	    return(NULL);
560|	}
561|	uri->fragment = NULL;
562|    }
563|    URL = xmlSaveUri(uri);
564|    xmlFreeURI(uri);
565|    if (URL == NULL) {
566|	xmlXIncludeErrMemory(ctxt, NULL, NULL);
567|	if (fragment != NULL)
568|	    xmlFree(fragment);
569|        xmlFree(URI);
570|	return(NULL);
571|    }
572|    xmlFree(URI);
573|
574|    if (xmlStrEqual(URL, ctxt->doc->URL))
575|	local = 1;
576|
577|    /*
578|     * If local and xml then we need a fragment
579|     */
580|    if ((local == 1) && (xml == 1) &&
581|        ((fragment == NULL) || (fragment[0] == 0))) {
582|	xmlXIncludeErr(ctxt, cur, XML_XINCLUDE_RECURSION,
583|	               "detected a local recursion with no xpointer in %s\n",
584|		       URL);
585|        xmlFree(URL);
586|        xmlFree(fragment);
587|	return(NULL);
588|    }
589|
590|    ref = xmlXIncludeNewRef(ctxt, URL, cur);
591|    xmlFree(URL);
592|    if (ref == NULL) {
593|        xmlFree(fragment);
594|	return(NULL);
595|    }
596|    ref->fragment = fragment;
597|    ref->xml = xml;
598|    return(ref);
599|}
